CREATE TABLE charges (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), contract_id UNIQUEIDENTIFIER NOT NULL, type NVARCHAR(20) NOT NULL, description NVARCHAR(1000) NULL, amount DECIMAL(19,2) NOT NULL, status NVARCHAR(30) NOT NULL, due_date DATE NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE payments (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), charge_id UNIQUEIDENTIFIER NOT NULL, customer_id UNIQUEIDENTIFIER NOT NULL, amount DECIMAL(19,2) NOT NULL, method NVARCHAR(30) NOT NULL, transaction_reference NVARCHAR(255) NULL, status NVARCHAR(30) NOT NULL, paid_at DATETIME2 NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
